insert into public.lessons (id, unit_id, sort_order, kind) values ('bc07333c-fdfc-54ae-92db-685e9d5e1167', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'introducing-yourself'), 1, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('bc07333c-fdfc-54ae-92db-685e9d5e1167', 'vi', 'Anh ấy, cô ấy', 'He dùng cho nam, she dùng cho nữ. His là của anh ấy, her là của cô ấy. Chọn his hay her theo người sở hữu, không theo đồ vật: Anna''s book là her book. He''s, she''s là dạng viết gọn của he is, she is.', 'She /ʃiː/ tròn môi, đẩy hơi như khi suỵt; đừng đọc thành see /siː/. Teacher có trọng âm ở âm tiết đầu: TEA-cher.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('bc07333c-fdfc-54ae-92db-685e9d5e1167', 'en-US', 'He and she', 'Use he for a man and she for a woman. His and her show who has something: Anna''s book is her book. He''s and she''s are short for he is and she is.', 'Say she with round lips, like shh. Do not say see. In teacher, the first part is strong: TEA-cher.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
