insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('65dfc66a-b78a-58b2-baa5-26ab22a3bd63', '571d8503-0bf7-57d5-990c-6e0728369903', 1, 'We''re new students here.', array['We are new students here.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('65dfc66a-b78a-58b2-baa5-26ab22a3bd63', 'vi', 'Chúng tôi là học sinh mới ở đây.', array['Chúng tôi là sinh viên mới ở đây.', 'Chúng mình là học viên mới ở đây.']::text[], null, '7eb04ffc89e1d4e5877ea5fbd1ae4631b0127803') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('4dd86c76-bdfd-5d3e-b03f-eb03bae24356', '571d8503-0bf7-57d5-990c-6e0728369903', 2, 'Are you students? Yes, we are.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('4dd86c76-bdfd-5d3e-b03f-eb03bae24356', 'vi', 'Các bạn là sinh viên à? Vâng, đúng vậy.', array['Các bạn là học sinh phải không? Vâng, đúng vậy.', 'Các bạn có phải là sinh viên không? Vâng, đúng rồi.']::text[], 'You dùng cho cả một người và nhiều người.', '9cd6ea1d5c02069e51da8dc50ab2352bb1538d50') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('4dd86c76-bdfd-5d3e-b03f-eb03bae24356', 'en-US', 'Are you students? Yes, we are.', '{}'::text[], 'You is for one person and for more than one person.', '9cd6ea1d5c02069e51da8dc50ab2352bb1538d50') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('d19756ae-708c-552e-b0aa-53112fa048d5', '571d8503-0bf7-57d5-990c-6e0728369903', 3, 'They''re from America. Their teacher is from England.', array['They are from America. Their teacher is from England.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('d19756ae-708c-552e-b0aa-53112fa048d5', 'vi', 'Họ đến từ Mỹ. Giáo viên của họ đến từ nước Anh.', array['Họ là người Mỹ. Giáo viên của họ là người Anh.', 'Họ đến từ Mỹ. Thầy giáo của họ đến từ Anh.']::text[], null, '43e1709b6798648b14eb1cd67cb4eb32887e7e33') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('be6976e4-cc73-5bb2-aea1-68e339e2e6b6', '571d8503-0bf7-57d5-990c-6e0728369903', 4, 'Are they your friends? Yes, they''re our friends.', array['Are they your friends? Yes, they are our friends.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('be6976e4-cc73-5bb2-aea1-68e339e2e6b6', 'vi', 'Họ là bạn của các bạn à? Vâng, họ là bạn của chúng tôi.', array['Họ có phải là bạn của các bạn không? Vâng, họ là bạn của chúng tôi.', 'Họ là bạn của các bạn à? Vâng, họ là bạn chúng tôi.']::text[], null, 'ab022fcf9b929a462fabd5d0a58a2a1591a5a588') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('e408ce46-a84b-52dd-b32f-e372427d1d2e', '571d8503-0bf7-57d5-990c-6e0728369903', 5, 'Excuse us, please.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('e408ce46-a84b-52dd-b32f-e372427d1d2e', 'vi', 'Xin lỗi, cho chúng tôi đi qua.', array['Xin lỗi, làm ơn cho chúng tôi qua.', 'Xin lỗi, cho chúng tôi qua.']::text[], 'Nói khi muốn đi qua chỗ có người đứng, hoặc khi cần rời đi.', 'd9aec377e023b0229308009c062e90abf9109ed5') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('e408ce46-a84b-52dd-b32f-e372427d1d2e', 'en-US', 'Excuse us, please.', '{}'::text[], 'Say it when you want to walk past people, or when you need to leave.', 'd9aec377e023b0229308009c062e90abf9109ed5') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
