insert into public.lessons (id, unit_id, sort_order, kind) values ('9fed32e4-945a-5c8e-b767-9ce8d98e11a4', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'introducing-yourself'), 4, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('9fed32e4-945a-5c8e-b767-9ce8d98e11a4', 'vi', 'Tôi sống ở đâu', 'Live in + thành phố: I live in Hanoi. Với he, she thêm -s: She lives in Hanoi. The dùng khi cả hai người đều biết đang nói về cái nào: the street (con phố đó).', 'City và email có trọng âm ở âm tiết đầu: CI-ty, E-mail. Address trong tiếng Anh Mỹ thường đọc AD-dress. Đọc rõ âm cuối /v/ trong live: răng trên chạm môi dưới.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('9fed32e4-945a-5c8e-b767-9ce8d98e11a4', 'en-US', 'Where I live', 'Say live in + a city: I live in Hanoi. With he and she, add -s: She lives in Hanoi. Use the when we both know which one: the street.', 'Say the first part strongly: CI-ty, E-mail, AD-dress. Say the last sound /v/ in live: your top teeth touch your bottom lip.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('60ce3dae-50ee-5af7-ac38-713c40fa26a5', (select id from public.courses where slug = 'english'), 'the', 'determiner', '/ˈðə/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
