insert into public.lessons (id, unit_id, sort_order, kind) values ('c5ee677b-8c7a-5daa-9c43-9908cd0ca66c', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'family'), 1, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('c5ee677b-8c7a-5daa-9c43-9908cd0ca66c', 'vi', 'Gia đình tôi', 'Số nhiều thường thêm -s: brother thành brothers, parent thành parents. Parents là bố mẹ (cả hai người). Tiếng Anh không phân biệt anh hay em: brother là anh trai hoặc em trai, sister là chị gái hoặc em gái.', 'Mother, father, brother có âm /ð/ ở giữa: đặt đầu lưỡi giữa hai hàm răng, cổ họng rung; đừng đọc thành /d/. Đuôi -er đọc nhẹ và cong lưỡi: MO-ther. Trong daughter, chữ gh không đọc: /ˈdɔtɚ/.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('c5ee677b-8c7a-5daa-9c43-9908cd0ca66c', 'en-US', 'My family', 'To make most nouns plural, add -s: brothers, parents. Parents means your mother and father. Brother and sister do not show who is older.', 'Mother, father and brother have /ð/ in the middle: put your tongue between your teeth. Say the -er ending softly. In daughter, do not say the gh.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
