insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('43c1eadd-0572-52d8-b9e1-e603c8395da4', 'vi', 'anh trai, em trai', array['anh trai', 'em trai', 'anh', 'em', 'anh em trai']::text[], 'Không phân biệt anh hay em. Muốn nói rõ thì dùng older brother (anh trai), younger brother (em trai).', 'd67cca5aaed6ead2e1c1c6b6e1d20a3d14c9622f') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
