insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('ec249973-4b6e-5e25-8ffd-908fd88451fb', 'vi', 'Đây là gia đình tôi.', array['Đây là gia đình của tôi.', 'Đây là gia đình mình.']::text[], null, 'efd1c8648e967bbd45693718b56d7c9fa4c4c7dd') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('dfeae7ab-0f80-5874-a65a-f843dbf8a19e', 'c5ee677b-8c7a-5daa-9c43-9908cd0ca66c', 2, 'This is my mother, and this is my father.', array['This is my mother and this is my father.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('dfeae7ab-0f80-5874-a65a-f843dbf8a19e', 'vi', 'Đây là mẹ tôi, còn đây là bố tôi.', array['Đây là mẹ tôi và đây là bố tôi.', 'Đây là mẹ của tôi, còn đây là bố của tôi.', 'Đây là mẹ tôi, còn đây là ba tôi.', 'Đây là mẹ tôi, còn đây là cha tôi.']::text[], null, '9d600faa4ba77f19081bde5699e64dc989b039e5') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
