insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('c50e3e64-7239-5159-9830-66e978289a5c', 'vi', 'Bố mẹ tôi đến từ Hà Nội.', array['Bố mẹ tôi là người Hà Nội.', 'Cha mẹ tôi đến từ Hà Nội.', 'Ba mẹ tôi đến từ Hà Nội.']::text[], null, '46917cc50a29010b2a80dcc8a566496468630e69') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('40464c30-ad94-5d55-9643-411cb696e188', 'c5ee677b-8c7a-5daa-9c43-9908cd0ca66c', 4, 'Are they your brothers? No, they''re my sons.', array['Are they your brothers? No, they are my sons.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('40464c30-ad94-5d55-9643-411cb696e188', 'vi', 'Họ là anh em trai của bạn à? Không, họ là con trai tôi.', array['Họ có phải là anh em trai của bạn không? Không, họ là con trai của tôi.', 'Họ là anh em của bạn à? Không, họ là các con trai tôi.', 'Đó là anh em trai của bạn à? Không, đó là các con trai tôi.']::text[], null, '1c4969d9d4f296a52115c5fa24d20bf225bbb9eb') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
