insert into public.lessons (id, unit_id, sort_order, kind) values ('005f9177-ce98-503b-9151-95d00c64bf5d', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'family'), 3, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('005f9177-ce98-503b-9151-95d00c64bf5d', 'vi', 'Họ hàng', 'Thêm ''s sau tên người để nói của ai: Anna''s aunt là cô của Anna, Minh''s cousins là anh chị em họ của Minh. With là với, cùng: I live with my grandparents.', 'Aunt trong tiếng Anh Mỹ đọc /ænt/, giống hệt ant (con kiến). Cousin đọc /ˈkʌzən/: chữ ou đọc như uncle, chữ s đọc /z/. Uncle và cousin nhấn vào âm đầu: UN-cle, COU-sin.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('005f9177-ce98-503b-9151-95d00c64bf5d', 'en-US', 'Relatives', 'Add ''s to a name to show who has something: Anna''s aunt, Minh''s cousins. With means together: I live with my grandparents.', 'In American English, aunt sounds like ant. In cousin, the s sounds like /z/. The first part is strong: UN-cle, COU-sin.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
