insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('a1c6c124-f709-545c-9423-a921a392a24b', 'vi', 'trông (có vẻ); nhìn', array['trông', 'nhìn', 'trông có vẻ', 'trông như']::text[], 'Look + tính từ là trông có vẻ: You look young. Với he, she thêm -s: She looks young.', 'e09315fa02d775f3e707a7af455093a1c240583b') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('a1c6c124-f709-545c-9423-a921a392a24b', 'en-US', 'to seem, from what you see; also to turn your eyes to something', '{}'::text[], 'Look + adjective: You look young. With he and she, add -s: She looks young.', 'e09315fa02d775f3e707a7af455093a1c240583b') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('2d476791-374b-554f-b028-c960b9048ccb', '1c07ee0e-0683-511b-8933-03eb874df379', 1, 'My brother is tall and very funny.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('2d476791-374b-554f-b028-c960b9048ccb', 'vi', 'Anh trai tôi cao và rất vui tính.', array['Em trai tôi cao và rất vui tính.', 'Anh trai tôi cao và rất hài hước.', 'Em trai tôi cao và rất hài hước.', 'Anh tôi cao và rất vui tính.']::text[], null, '541dfc23f44db7f7ed1565a12b07093fd0e1b19f') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('0ebb8758-6841-525a-b17a-2134fc0a6705', '1c07ee0e-0683-511b-8933-03eb874df379', 2, 'She has long black hair.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('0ebb8758-6841-525a-b17a-2134fc0a6705', 'vi', 'Cô ấy có mái tóc đen dài.', array['Cô ấy có tóc dài màu đen.', 'Cô ấy có mái tóc dài màu đen.', 'Chị ấy có mái tóc đen dài.', 'Cô ấy có tóc đen dài.']::text[], null, '7f4ed9df34931cee0f22509ce5b9fa9a86032586') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('f434a1a3-ac69-5605-af21-a4342636cfea', '1c07ee0e-0683-511b-8933-03eb874df379', 3, 'He has brown eyes.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('f434a1a3-ac69-5605-af21-a4342636cfea', 'vi', 'Anh ấy có đôi mắt màu nâu.', array['Anh ấy có mắt nâu.', 'Anh ấy có đôi mắt nâu.', 'Mắt anh ấy màu nâu.']::text[], 'Mắt đen của người Việt thường được gọi là brown eyes hoặc dark brown eyes. A black eye nghĩa là mắt bị đánh thâm tím.', '9917b11a74076d0a479feed5362b37835b051fcc') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('f434a1a3-ac69-5605-af21-a4342636cfea', 'en-US', 'He has brown eyes.', '{}'::text[], 'Dark eyes are usually called brown eyes. A black eye is an eye hurt in a fight.', '9917b11a74076d0a479feed5362b37835b051fcc') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('87da0001-4e62-5661-b516-54673aba3d7a', '1c07ee0e-0683-511b-8933-03eb874df379', 4, 'Your mother looks very young.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('87da0001-4e62-5661-b516-54673aba3d7a', 'vi', 'Mẹ bạn trông rất trẻ.', array['Mẹ của bạn trông rất trẻ.', 'Mẹ bạn nhìn rất trẻ.', 'Mẹ bạn trông trẻ lắm.']::text[], null, '1f1db87637f60c9bd9a8af1488f66b5fa48ec974') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('5daa3822-1f26-5aa8-9e51-292ba68a5a89', '1c07ee0e-0683-511b-8933-03eb874df379', 5, 'My grandmother is old, but she''s very kind.', array['My grandmother is old, but she is very kind.', 'My grandmother is old but she''s very kind.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('5daa3822-1f26-5aa8-9e51-292ba68a5a89', 'vi', 'Bà tôi già rồi, nhưng bà rất tốt bụng.', array['Bà tôi già nhưng rất tốt bụng.', 'Bà của tôi đã già, nhưng bà rất tốt bụng.', 'Bà tôi già rồi nhưng rất hiền.']::text[], null, '754d7ef910e8038164bbbf689fc80354cf58dbed') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
